#include <bits/stdc++.h>
using namespace std;

static char buf[1 << 16];
static size_t blen = 0, bpos = 0;
static inline int gc() {
    if (bpos == blen) {
        blen = fread(buf, 1, sizeof buf, stdin);
        bpos = 0;
        if (!blen) return -1;
    }
    return buf[bpos++];
}
static long long readLong() {
    int c = gc();
    while (c != '-' && (c < '0' || c > '9')) {
        if (c == -1) return 0;
        c = gc();
    }
    bool neg = false;
    if (c == '-') { neg = true; c = gc(); }
    long long v = 0;
    while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
    return neg ? -v : v;
}

int main() {
    int n = (int)readLong();
    vector<long long> cap(n), load(n);
    for (auto &v : cap) v = readLong();
    for (auto &v : load) v = readLong();
    // Smallest capacity gets the largest load; equal capacities go by descending index
    // so the smaller index ends up with the smaller load of its group.
    sort(load.rbegin(), load.rend());
    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) { return cap[a] != cap[b] ? cap[a] < cap[b] : a > b; });
