}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream in = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int gc() throws IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = gc();
        while (c != '-' && (c < '0' || c > '9')) {
            if (c == -1) return 0;
            c = gc();
        }
        boolean neg = false;
        if (c == '-') { neg = true; c = gc(); }
        long v = 0;
        while (c >= '0' && c <= '9') { v = v * 10 + (c - '0'); c = gc(); }
        return neg ? -v : v;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        long[] cap = new long[n], load = new long[n];
        for (int i = 0; i < n; i++) cap[i] = nextLong();
        for (int i = 0; i < n; i++) load[i] = nextLong();
        // Smallest capacity gets the largest load; equal capacities go by descending index
        // so the smaller index ends up with the smaller load of its group.
        Arrays.sort(load); // ascending: load[n-1-j] is the j-th largest
        // Pack (capacity, reversed index) into one long: capacity shifted to non-negative.
        long[] key = new long[n];
        for (int i = 0; i < n; i++) key[i] = ((cap[i] + 1_000_000_000L) << 18) | (n - 1 - i);
        Arrays.sort(key);
        long[] out = new long[n];
        for (int j = 0; j < n; j++) out[n - 1 - (int) (key[j] & ((1 << 18) - 1))] = load[n - 1 - j];
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) { if (i > 0) sb.append(' '); sb.append(out[i]); }
        sb.append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"slices"
	"sort"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<16)

func readInt() int64 {
	c, err := rd.ReadByte()
	for err == nil && c != '-' && (c < '0' || c > '9') {
		c, err = rd.ReadByte()
	}
	if err != nil {
		return 0
	}
	neg := false
	if c == '-' {
		neg = true
		c, err = rd.ReadByte()
	}
	var v int64
	for err == nil && c >= '0' && c <= '9' {
		v = v*10 + int64(c-'0')
		c, err = rd.ReadByte()
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	n := int(readInt())
	capacity, load := make([]int64, n), make([]int64, n)
	for i := range capacity {
		capacity[i] = readInt()
	}
	for i := range load {
		load[i] = readInt()
	}
	// Smallest capacity gets the largest load; equal capacities go by descending index
	// so the smaller index ends up with the smaller load of its group.
	slices.Sort(load)
	slices.Reverse(load)
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.Slice(order, func(x, y int) bool {
		a, b := order[x], order[y]
		if capacity[a] != capacity[b] {
			return capacity[a] < capacity[b]
		}
		return a > b
	})
	out := make([]int64, n)
	for j, i := range order {
		out[i] = load[j]
	}
	buf := make([]byte, 0, 12*n)
	for i, v := range out {
		if i > 0 {
			buf = append(buf, ' ')
		}
		buf = strconv.AppendInt(buf, v, 10)
	}
	buf = append(buf, '\n')
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.Write(buf)
}
